import test from 'node:test';
import assert from 'node:assert/strict';
import { rankFileCandidates, scoreFileName } from '../src/file-fuzzy-model.mjs';

// Expected numbers were derived from the documented degree arithmetic, not
// captured by running Codex or generated by evaluating its private matcher.
test('prefix, complete-name and exact-case weights have independently derived scores', () => {
  for (const [name, expected] of [['foo', 110037], ['foo.ts', 110024], ['Foo.ts', 110004], ['FOO.ts', 110004], ['xfoo', 16], ['myFoo', 10005]]) {
    assert.equal(scoreFileName('foo', name).score, expected, name);
  }
});

test('ordinary query case and surrounding whitespace are normalized, candidate case is not', () => {
  assert.deepEqual(scoreFileName('  FOO\n', 'Foo.ts'), scoreFileName('foo', 'Foo.ts'));
  assert.equal(scoreFileName('foo', 'foo.ts').score - scoreFileName('foo', 'Foo.ts').score, 20);
});

test('fragment splitting, camel boundary, and later-fragment penalty', () => {
  const result = scoreFileName('fb', 'fooBar');
  assert.equal(result.score, 109914);
  assert.deepEqual(result.indices, [0, 3]);
  assert.deepEqual(result.fragments, [{ start: 0, end: 1 }, { start: 3, end: 4 }]);
  assert.equal(scoreFileName('fb', 'foo_bar').score, 109913);
});

test('arbitrary subsequence matching does not replace fragment eligibility', () => {
  assert.equal(scoreFileName('abc', 'axbyc').matched, false);
  assert.equal(scoreFileName('fb', 'foobar').matched, false);
  assert.equal(scoreFileName('f*b', 'foobar').matched, true);
  assert.deepEqual(scoreFileName('f*b', 'foobar').indices, [0, 3]);
});

test('internal space is a wildcard with a word-boundary restriction', () => {
  assert.deepEqual(scoreFileName('f b', 'fooBar').indices, [0, 3]);
  assert.equal(scoreFileName('f b', 'foobar').matched, false);
});

test('a short entire remaining match can succeed inside a word', () => {
  assert.deepEqual(scoreFileName('fo', 'xfo').indices, [1, 2]);
});

test('adjacent numeric query characters cannot skip a candidate digit', () => {
  assert.equal(scoreFileName('12', '132').matched, false);
  assert.equal(scoreFileName('12', 'item12').matched, true);
  assert.equal(scoreFileName('1*2', '132').matched, true);
});

test('a dotted query cannot jump across an unrelated intervening dot', () => {
  assert.equal(scoreFileName('ab.c', 'a.zzB.c').matched, false);
  assert.equal(scoreFileName('ab.c', 'aB.c').matched, true);
});

test('path query falls back to a prefix of the basename, not a substring', () => {
  for (const query of ['src/foo', 'src\\foo']) {
    const result = scoreFileName(query, 'foo.ts');
    assert.equal(result.matchMode, 'path-basename-fallback');
    assert.equal(result.score, 110024);
    assert.deepEqual(result.indices, [0, 1, 2]);
    assert.equal(scoreFileName(query, 'xfoo.ts').score, 0);
  }
});

test('primary path pattern can match a supplied separator-containing label', () => {
  const result = scoreFileName('src/foo', 'src\\foo');
  assert.equal(result.matchMode, 'primary');
  assert.deepEqual(result.indices, [0, 1, 2, 3, 4, 5, 6]);
});

test('trailing separator does not silently become a basename query', () => {
  assert.equal(scoreFileName('src/foo/', 'foo').score, 0);
  assert.equal(scoreFileName('src\\foo\\', 'foo').score, 0);
});

test('ranking uses file_name rather than relative path or native score', () => {
  const results = rankFileCandidates('foo', [
    { id: 'path-only', file_name: 'bar.ts', path: 'foo/bar.ts', score: 999999 },
    { id: 'basename', file_name: 'foo.ts', path: 'other/foo.ts', score: -100 }
  ]);
  assert.deepEqual(results.map(x => x.id), ['basename', 'path-only']);
  assert.equal(results[1].score, 0);
  assert.equal(results[0].score, 110024);
});

test('zero-score candidates stay in the returned candidate set', () => {
  const results = rankFileCandidates('unmatched', [{ path: 'b.txt' }, { path: 'A.txt' }]);
  assert.equal(results.length, 2);
  assert.ok(results.every(x => x.score === 0 && !x.matched));
  assert.deepEqual(results.map(x => x.file_name), ['A.txt', 'b.txt']);
});

test('equal scores use raw JS label order, not locale or natural ordering', () => {
  const labels = ['a2', 'a10', 'a', 'A', '😀', '\ue000'];
  assert.deepEqual(rankFileCandidates('no-match', labels.map(file_name => ({ file_name }))).map(x => x.file_name),
    ['A', 'a', 'a10', 'a2', '😀', '\ue000']);
});

test('identical basenames preserve original index, not root or path order', () => {
  const candidates = [{ path: 'z/foo.ts', root: '/z' }, { path: 'a/foo.ts', root: '/a' }];
  assert.deepEqual(rankFileCandidates('foo', candidates).map(x => x.path), ['z/foo.ts', 'a/foo.ts']);
});

test('empty query preserves supplied order and yields no client highlights', () => {
  const candidates = [{ path: 'z.ts' }, { path: 'a.ts' }];
  const results = rankFileCandidates(' \n ', candidates);
  assert.deepEqual(results.map(x => x.path), ['z.ts', 'a.ts']);
  assert.ok(results.every(x => x.score === 0 && x.indices.length === 0));
});

test('indices and length penalty use UTF-16 units, including surrogate pairs', () => {
  const result = scoreFileName('😀', '😀.md');
  assert.deepEqual(result.indices, [0, 1]);
  assert.equal(result.score, 110025);
  assert.equal(scoreFileName('foo', 'foo😀').score, 110025);
});

test('literal Chinese works without claiming pinyin or accent normalization', () => {
  assert.equal(scoreFileName('图', '图文.md').score, 110025);
  assert.equal(scoreFileName('tu', '图文.md').matched, false);
  assert.equal(scoreFileName('cafe', 'café.txt').matched, false);
});

test('lowercasing that expands UTF-16 length preserves the original character', () => {
  const result = scoreFileName('İ', 'İ');
  assert.equal(result.score, 110529);
  assert.deepEqual(result.indices, [0]);
  assert.equal(scoreFileName('İ', 'i').matched, false);
});

test('compiled pattern threshold includes the automatically inserted star', () => {
  assert.equal(scoreFileName('a'.repeat(99), 'a'.repeat(99)).longPattern, false);
  const long = scoreFileName('a'.repeat(100), 'a'.repeat(100));
  assert.equal(long.longPattern, true);
  assert.equal(long.score, 109940);
  assert.equal(long.indices.length, 100);
});

test('long-pattern fallback removes stars but treats internal spaces literally', () => {
  const query = 'a'.repeat(98) + ' b';
  assert.equal(scoreFileName(query, 'a'.repeat(98) + 'B').matched, false);
  const match = scoreFileName(query, 'x' + 'a'.repeat(98) + ' b');
  assert.equal(match.longPattern, true);
  assert.equal(match.indices[0], 1);
});

test('wildcard-only patterns produce a positive match with no fragments', () => {
  assert.deepEqual(scoreFileName('*', 'foo').indices, []);
  assert.equal(scoreFileName('*', 'foo').score, 1);
});

test('input objects and native indices are not mutated', () => {
  const nativeIndices = Object.freeze([4, 5]);
  const candidate = Object.freeze({ path: 'src/foo', indices: nativeIndices, score: 3 });
  const input = Object.freeze([candidate]);
  const [result] = rankFileCandidates('foo', input);
  assert.deepEqual(result.indices, [0, 1, 2]);
  assert.equal(candidate.score, 3);
  assert.equal(candidate.indices, nativeIndices);
  assert.notEqual(result, candidate);
});

test('missing file_name derives basename from either path separator', () => {
  assert.equal(rankFileCandidates('foo', [{ path: 'C:\\src\\foo.ts' }])[0].file_name, 'foo.ts');
  assert.equal(rankFileCandidates('foo', [{ path: 'src/foo.ts', label: 'chosen.foo' }])[0].file_name, 'chosen.foo');
});
